package net.fabricmc.fabric.api.event.player;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;

/** Fabric API callback (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
@FunctionalInterface
public interface UseItemCallback {
    Event<UseItemCallback> EVENT = EventFactory.createArrayBacked(UseItemCallback.class, ls -> (player, world, hand) -> { for (UseItemCallback l : ls) { var r = l.interact(player, world, hand); if (r.getResult() != InteractionResult.PASS) return r; } return InteractionResultHolder.pass(player.getItemInHand(hand)); });

    InteractionResultHolder<ItemStack> interact(Player player, Level world, InteractionHand hand);
}
